cafienne:implementation.task-model:
{
  "schema": {
    "title": "Employee details",
    "description": "Personal details and the role of the new employee. Save draft keeps the form; Save & continue creates the account and opens the Equipment request by HR.",
    "type": "object",
    "properties": {
      "Details": {
        "type": "object",
        "x-pii": "employee",
        "x-on-complete": "createEmployee"
      },
      "swag": {
        "type": "object",
        "title": "Welcome kit",
        "properties": {
          "size": {
            "type": "string",
            "title": "T-shirt size",
            "oneOf": [
              { "const": "S", "title": "S" },
              { "const": "M", "title": "M" },
              { "const": "L", "title": "L" },
              { "const": "XL", "title": "XL" }
            ]
          },
          "hoodieSize": {
            "type": "string",
            "title": "Hoodie size",
            "oneOf": [
              { "const": "S", "title": "S" },
              { "const": "M", "title": "M" },
              { "const": "L", "title": "L" },
              { "const": "XL", "title": "XL" }
            ]
          }
        }
      }
    }
  },
  "uiSchema": {
    "type": "VerticalLayout",
    "elements": [
          {
        "type": "Group",
        "label": "Welcome kit",
        "elements": [
          { "type": "Control", "scope": "#/properties/swag/properties/size" },
          { "type": "Control", "scope": "#/properties/swag/properties/hoodieSize" }
        ]
      },
      { "type": "PiiSection", "scope": "#/properties/Details" }
    ]
  },
  "submitLabel": "Save & continue"
}

{
  "schema": {
    "title": "Equipment request by HR",
    "description": "What IT should prepare for the new employee. Send to IT gives the IT admin an Equipment approval by IT task.",
    "type": "object",
    "properties": {
      "Onboarding": {
        "type": "object",
        "x-on-complete": "sendToIt",
        "required": ["ITRequest"],
        "properties": {
          "ITRequest": {
            "type": "object",
            "required": ["itLaptopModel", "itReadyBy", "itDeliveryMethod", "itKeyboardLayout"],
            "properties": {
              "itLaptopModel": { "type": "string", "title": "Laptop", "enum": ["MacBook Pro 14\"", "MacBook Air 13\"", "Dell XPS 15", "Windows standard"] },
              "itReadyBy": { "type": "string", "title": "Ready by", "format": "date" },
              "itDeliveryMethod": {
                "type": "string", "title": "Delivery",
                "oneOf": [
                  { "const": "OFFICE_DAY1", "title": "Pick up at office on day 1" },
                  { "const": "SHIP_HOME", "title": "Ship to home address" }
                ]
              },
              "itKeyboardLayout": { "type": "string", "title": "Keyboard layout", "enum": ["US International", "Dutch"] },
              "itAccessories": {
                "type": "array", "title": "Accessories", "uniqueItems": true,
                "items": { "type": "string", "enum": ["Monitor", "Keyboard & mouse", "Headset", "Docking station", "Phone", "Access badge"] }
              },
              "itAccounts": {
                "type": "array", "title": "Accounts & software", "uniqueItems": true,
                "items": { "type": "string", "enum": ["Microsoft 365 / e-mail", "Slack", "VPN", "Jira / Confluence", "GitHub", "Figma", "AWS console", "Docker Desktop"] }
              },
              "itNotes": { "type": "string", "title": "Notes for IT" }
            }
          }
        }
      }
    }
  },
  "uiSchema": {
    "type": "VerticalLayout",
    "elements": [
      {
        "type": "Group",
        "label": "Laptop & hardware",
        "elements": [
          { "type": "HorizontalLayout", "elements": [
            { "type": "Control", "scope": "#/properties/Onboarding/properties/ITRequest/properties/itLaptopModel" },
            { "type": "Control", "scope": "#/properties/Onboarding/properties/ITRequest/properties/itReadyBy" } ] },
          { "type": "HorizontalLayout", "elements": [
            { "type": "Control", "scope": "#/properties/Onboarding/properties/ITRequest/properties/itDeliveryMethod" },
            { "type": "Control", "scope": "#/properties/Onboarding/properties/ITRequest/properties/itKeyboardLayout" } ] },
          { "type": "Control", "scope": "#/properties/Onboarding/properties/ITRequest/properties/itAccessories" }
        ]
      },
      {
        "type": "Group",
        "label": "Accounts & software",
        "elements": [
          { "type": "Control", "scope": "#/properties/Onboarding/properties/ITRequest/properties/itAccounts" },
          { "type": "Control", "scope": "#/properties/Onboarding/properties/ITRequest/properties/itNotes", "options": { "multi": true } }
        ]
      }
    ]
  },
  "submitLabel": "Send to IT"
}

{
  "schema": {
    "title": "Equipment approval by IT",
    "description": "Record each item you issue: it is added to the employee's assets and ticks the matching checklist item. Tick the accounts on the checklist below, then Mark setup done.",
    "type": "object",
    "properties": {
      "Onboarding": {
        "type": "object",
        "x-on-complete": "itSetupDone",
        "properties": {
          "ITRequest": {
            "type": "object",
            "title": "Requested by HR",
            "readOnly": true,
            "properties": {
              "itLaptopModel": { "type": "string", "title": "Laptop" },
              "itKeyboardLayout": { "type": "string", "title": "Keyboard layout" },
              "itReadyBy": { "type": "string", "title": "Ready by", "format": "date" },
              "itDeliveryMethod": {
                "type": "string", "title": "Delivery",
                "oneOf": [
                  { "const": "OFFICE_DAY1", "title": "Pick up at office on day 1" },
                  { "const": "SHIP_HOME", "title": "Ship to home address" }
                ]
              },
              "itAccessories": {
                "type": "array", "title": "Accessories", "uniqueItems": true,
                "items": { "type": "string", "enum": ["Monitor", "Keyboard & mouse", "Headset", "Docking station", "Phone", "Access badge"] }
              },
              "itAccounts": {
                "type": "array", "title": "Accounts & software", "uniqueItems": true,
                "items": { "type": "string", "enum": ["Microsoft 365 / e-mail", "Slack", "VPN", "Jira / Confluence", "GitHub", "Figma", "AWS console", "Docker Desktop"] }
              },
              "itNotes": { "type": "string", "title": "Notes" }
            }
          },
          "Assets": {
            "type": "array",
            "title": "Equipment issued",
            "items": {
              "type": "object",
              "required": ["assetType", "model", "assetNumber", "issuedOn"],
              "properties": {
                "assetType": {
                  "type": "string", "title": "Type",
                  "oneOf": [
                    { "const": "LAPTOP", "title": "Laptop" },
                    { "const": "MONITOR", "title": "Monitor" },
                    { "const": "PHONE", "title": "Phone" },
                    { "const": "ACCESS_BADGE", "title": "Access badge" },
                    { "const": "DOCKING_STATION", "title": "Docking station" },
                    { "const": "HEADSET", "title": "Headset" },
                    { "const": "KEYBOARD_MOUSE", "title": "Keyboard & mouse" },
                    { "const": "OTHER", "title": "Other" }
                  ]
                },
                "model": { "type": "string", "title": "Model" },
                "assetNumber": { "type": "string", "title": "Asset no." },
                "serialNumber": { "type": "string", "title": "Serial number" },
                "issuedOn": { "type": "string", "title": "Issue date", "format": "date" }
              }
            }
          }
        }
      }
    }
  },
  "uiSchema": {
    "type": "VerticalLayout",
    "elements": [
      {
        "type": "Group",
        "label": "Requested by HR",
        "options": { "readonly": true },
        "elements": [
          { "type": "HorizontalLayout", "elements": [
            { "type": "Control", "scope": "#/properties/Onboarding/properties/ITRequest/properties/itLaptopModel" },
            { "type": "Control", "scope": "#/properties/Onboarding/properties/ITRequest/properties/itKeyboardLayout" } ] },
          { "type": "HorizontalLayout", "elements": [
            { "type": "Control", "scope": "#/properties/Onboarding/properties/ITRequest/properties/itReadyBy" },
            { "type": "Control", "scope": "#/properties/Onboarding/properties/ITRequest/properties/itDeliveryMethod" } ] },
          { "type": "Control", "scope": "#/properties/Onboarding/properties/ITRequest/properties/itAccessories" },
          { "type": "Control", "scope": "#/properties/Onboarding/properties/ITRequest/properties/itAccounts" },
          { "type": "Control", "scope": "#/properties/Onboarding/properties/ITRequest/properties/itNotes", "options": { "multi": true } }
        ]
      },
      {
        "type": "Group",
        "label": "Equipment issued",
        "elements": [
          { "type": "Control", "scope": "#/properties/Onboarding/properties/Assets", "label": "Issued items", "options": { "table": true } }
        ]
      }
    ]
  },
  "submitLabel": "Mark setup done"
}

{
  "schema": {
    "title": "Define goals & plan",
    "description": "Set the plan period and add your goals: what you want to develop, how you will know it is achieved and by when. The plan then goes to your manager for approval.",
    "type": "object",
    "required": [
      "Plan"
    ],
    "properties": {
      "Plan": {
        "type": "object",
        "title": "Development plan",
        "properties": {
          "period": {
            "type": "string",
            "title": "Plan period"
          },
          "goals": {
            "type": "array",
            "title": "Goals",
            "items": {
              "type": "object",
              "properties": {
                "title": {
                  "type": "string",
                  "title": "Goal"
                },
                "type": {
                  "type": "string",
                  "title": "Type",
                  "oneOf": [
                    {
                      "const": "SKILL",
                      "title": "Skill"
                    },
                    {
                      "const": "KNOWLEDGE",
                      "title": "Knowledge"
                    },
                    {
                      "const": "BEHAVIOUR",
                      "title": "Behaviour"
                    },
                    {
                      "const": "CAREER",
                      "title": "Career"
                    }
                  ]
                },
                "description": {
                  "type": "string",
                  "title": "Description"
                },
                "successCriteria": {
                  "type": "string",
                  "title": "How we know it is achieved"
                },
                "targetDate": {
                  "type": "string",
                  "title": "Target date",
                  "format": "date"
                }
              },
              "required": [
                "title",
                "type",
                "successCriteria",
                "targetDate"
              ]
            },
            "minItems": 1
          }
        },
        "x-on-complete": "submitPlan",
        "required": [
          "period",
          "goals"
        ]
      }
    }
  },
  "uiSchema": {
    "type": "VerticalLayout",
    "elements": [
      {
        "type": "Group",
        "label": "Plan",
        "elements": [
          {
            "type": "Control",
            "scope": "#/properties/Plan/properties/period"
          },
          {
            "type": "Control",
            "scope": "#/properties/Plan/properties/goals",
            "label": "Goals",
            "options": {
              "table": true
            }
          }
        ]
      }
    ]
  },
  "submitLabel": "Send for approval"
}

{
  "schema": {
    "title": "Approve plan",
    "description": "Read the plan and approve it, or send it back with comments.",
    "type": "object",
    "required": [
      "Approval"
    ],
    "properties": {
      "Plan": {
        "type": "object",
        "title": "Development plan",
        "properties": {
          "period": {
            "type": "string",
            "title": "Plan period"
          },
          "goals": {
            "type": "array",
            "title": "Goals",
            "items": {
              "type": "object",
              "properties": {
                "title": {
                  "type": "string",
                  "title": "Goal"
                },
                "type": {
                  "type": "string",
                  "title": "Type",
                  "oneOf": [
                    {
                      "const": "SKILL",
                      "title": "Skill"
                    },
                    {
                      "const": "KNOWLEDGE",
                      "title": "Knowledge"
                    },
                    {
                      "const": "BEHAVIOUR",
                      "title": "Behaviour"
                    },
                    {
                      "const": "CAREER",
                      "title": "Career"
                    }
                  ]
                },
                "description": {
                  "type": "string",
                  "title": "Description"
                },
                "successCriteria": {
                  "type": "string",
                  "title": "How we know it is achieved"
                },
                "targetDate": {
                  "type": "string",
                  "title": "Target date",
                  "format": "date"
                }
              }
            }
          }
        },
        "readOnly": true
      },
      "Approval": {
        "type": "object",
        "title": "Decision",
        "x-on-complete": "decidePlan",
        "required": [
          "decision"
        ],
        "properties": {
          "decision": {
            "type": "string",
            "title": "Decision",
            "oneOf": [
              {
                "const": "APPROVED",
                "title": "Approve"
              },
              {
                "const": "REJECTED",
                "title": "Send back for changes"
              }
            ]
          },
          "comments": {
            "type": "string",
            "title": "Comments"
          }
        }
      }
    }
  },
  "uiSchema": {
    "type": "VerticalLayout",
    "elements": [
      {
        "type": "Group",
        "label": "Plan",
        "elements": [
          {
            "type": "Control",
            "scope": "#/properties/Plan/properties/period"
          },
          {
            "type": "Control",
            "scope": "#/properties/Plan/properties/goals",
            "label": "Goals",
            "options": {
              "table": true
            }
          }
        ],
        "options": {
          "readonly": true
        }
      },
      {
        "type": "Group",
        "label": "Decision",
        "elements": [
          {
            "type": "Control",
            "scope": "#/properties/Approval/properties/decision"
          },
          {
            "type": "Control",
            "scope": "#/properties/Approval/properties/comments",
            "options": {
              "multi": true
            }
          }
        ]
      }
    ]
  },
  "submitLabel": "Save decision"
}

{
  "schema": {
    "title": "Revise plan",
    "description": "Your manager sent the plan back. Change it and send it for approval again.",
    "type": "object",
    "required": [
      "Plan"
    ],
    "properties": {
      "Approval": {
        "type": "object",
        "title": "Manager's decision",
        "readOnly": true,
        "properties": {
          "decision": {
            "type": "string",
            "title": "Decision",
            "oneOf": [
              {
                "const": "APPROVED",
                "title": "Approved"
              },
              {
                "const": "REJECTED",
                "title": "Sent back for changes"
              }
            ]
          },
          "comments": {
            "type": "string",
            "title": "Comments"
          }
        }
      },
      "Plan": {
        "type": "object",
        "title": "Development plan",
        "properties": {
          "period": {
            "type": "string",
            "title": "Plan period"
          },
          "goals": {
            "type": "array",
            "title": "Goals",
            "items": {
              "type": "object",
              "properties": {
                "title": {
                  "type": "string",
                  "title": "Goal"
                },
                "type": {
                  "type": "string",
                  "title": "Type",
                  "oneOf": [
                    {
                      "const": "SKILL",
                      "title": "Skill"
                    },
                    {
                      "const": "KNOWLEDGE",
                      "title": "Knowledge"
                    },
                    {
                      "const": "BEHAVIOUR",
                      "title": "Behaviour"
                    },
                    {
                      "const": "CAREER",
                      "title": "Career"
                    }
                  ]
                },
                "description": {
                  "type": "string",
                  "title": "Description"
                },
                "successCriteria": {
                  "type": "string",
                  "title": "How we know it is achieved"
                },
                "targetDate": {
                  "type": "string",
                  "title": "Target date",
                  "format": "date"
                }
              },
              "required": [
                "title",
                "type",
                "successCriteria",
                "targetDate"
              ]
            },
            "minItems": 1
          }
        },
        "x-on-complete": "submitPlan",
        "required": [
          "period",
          "goals"
        ]
      }
    }
  },
  "uiSchema": {
    "type": "VerticalLayout",
    "elements": [
      {
        "type": "Group",
        "label": "Manager's decision",
        "elements": [
          {
            "type": "Control",
            "scope": "#/properties/Approval/properties/decision"
          },
          {
            "type": "Control",
            "scope": "#/properties/Approval/properties/comments",
            "options": {
              "multi": true
            }
          }
        ],
        "options": {
          "readonly": true
        }
      },
      {
        "type": "Group",
        "label": "Plan",
        "elements": [
          {
            "type": "Control",
            "scope": "#/properties/Plan/properties/period"
          },
          {
            "type": "Control",
            "scope": "#/properties/Plan/properties/goals",
            "label": "Goals",
            "options": {
              "table": true
            }
          }
        ]
      }
    ]
  },
  "submitLabel": "Send for approval"
}

{
  "schema": {
    "title": "Review progress",
    "description": "Record how the plan is going. Tick \"The plan has been carried out\" to start the evaluation; otherwise the next check is in 14 days.",
    "type": "object",
    "required": [
      "ProgressReview"
    ],
    "properties": {
      "Plan": {
        "type": "object",
        "title": "Development plan",
        "properties": {
          "period": {
            "type": "string",
            "title": "Plan period"
          },
          "goals": {
            "type": "array",
            "title": "Goals",
            "items": {
              "type": "object",
              "properties": {
                "title": {
                  "type": "string",
                  "title": "Goal"
                },
                "type": {
                  "type": "string",
                  "title": "Type",
                  "oneOf": [
                    {
                      "const": "SKILL",
                      "title": "Skill"
                    },
                    {
                      "const": "KNOWLEDGE",
                      "title": "Knowledge"
                    },
                    {
                      "const": "BEHAVIOUR",
                      "title": "Behaviour"
                    },
                    {
                      "const": "CAREER",
                      "title": "Career"
                    }
                  ]
                },
                "description": {
                  "type": "string",
                  "title": "Description"
                },
                "successCriteria": {
                  "type": "string",
                  "title": "How we know it is achieved"
                },
                "targetDate": {
                  "type": "string",
                  "title": "Target date",
                  "format": "date"
                }
              }
            }
          }
        },
        "readOnly": true
      },
      "Activities": {
        "type": "array",
        "title": "Activities",
        "readOnly": true,
        "items": {
          "type": "object",
          "properties": {
            "type": {
              "type": "string",
              "title": "Type",
              "oneOf": [
                {
                  "const": "PROJECT",
                  "title": "Project"
                },
                {
                  "const": "TRAINING",
                  "title": "Training"
                },
                {
                  "const": "COACHING",
                  "title": "Coaching"
                }
              ]
            },
            "description": {
              "type": "string",
              "title": "Activity"
            },
            "relatedGoal": {
              "type": "string",
              "title": "For goal"
            },
            "dueDate": {
              "type": "string",
              "title": "Due",
              "format": "date"
            },
            "status": {
              "type": "string",
              "title": "Status",
              "oneOf": [
                {
                  "const": "PLANNED",
                  "title": "Planned"
                },
                {
                  "const": "IN_PROGRESS",
                  "title": "In progress"
                },
                {
                  "const": "DONE",
                  "title": "Done"
                }
              ]
            },
            "outcome": {
              "type": "string",
              "title": "Outcome"
            }
          }
        }
      },
      "ProgressReviews": {
        "type": "array",
        "title": "Earlier reviews",
        "readOnly": true,
        "items": {
          "type": "object",
          "properties": {
            "date": {
              "type": "string",
              "title": "Review date",
              "format": "date"
            },
            "onTrack": {
              "type": "boolean",
              "title": "On track"
            },
            "notes": {
              "type": "string",
              "title": "Notes"
            },
            "adjustments": {
              "type": "string",
              "title": "Adjustments to the plan"
            },
            "planCompleted": {
              "type": "boolean",
              "title": "The plan has been carried out"
            }
          }
        }
      },
      "ProgressReview": {
        "type": "object",
        "title": "Progress review",
        "x-on-complete": "addReview",
        "required": [
          "date",
          "notes"
        ],
        "properties": {
          "date": {
            "type": "string",
            "title": "Review date",
            "format": "date"
          },
          "onTrack": {
            "type": "boolean",
            "title": "On track",
            "default": true
          },
          "notes": {
            "type": "string",
            "title": "Notes"
          },
          "adjustments": {
            "type": "string",
            "title": "Adjustments to the plan"
          },
          "planCompleted": {
            "type": "boolean",
            "title": "The plan has been carried out",
            "default": false
          }
        }
      }
    }
  },
  "uiSchema": {
    "type": "VerticalLayout",
    "elements": [
      {
        "type": "Group",
        "label": "Plan",
        "elements": [
          {
            "type": "Control",
            "scope": "#/properties/Plan/properties/period"
          },
          {
            "type": "Control",
            "scope": "#/properties/Plan/properties/goals",
            "label": "Goals",
            "options": {
              "table": true
            }
          }
        ],
        "options": {
          "readonly": true
        }
      },
      {
        "type": "Group",
        "label": "Activities",
        "elements": [
          {
            "type": "Control",
            "scope": "#/properties/Activities",
            "label": false,
            "options": {
              "table": true
            }
          }
        ],
        "options": {
          "readonly": true
        }
      },
      {
        "type": "Group",
        "label": "Earlier progress reviews",
        "elements": [
          {
            "type": "Control",
            "scope": "#/properties/ProgressReviews",
            "label": false,
            "options": {
              "table": true
            }
          }
        ],
        "options": {
          "readonly": true
        }
      },
      {
        "type": "Group",
        "label": "This review",
        "elements": [
          {
            "type": "HorizontalLayout",
            "elements": [
              {
                "type": "Control",
                "scope": "#/properties/ProgressReview/properties/date"
              },
              {
                "type": "Control",
                "scope": "#/properties/ProgressReview/properties/onTrack"
              }
            ]
          },
          {
            "type": "Control",
            "scope": "#/properties/ProgressReview/properties/notes",
            "options": {
              "multi": true
            }
          },
          {
            "type": "Control",
            "scope": "#/properties/ProgressReview/properties/adjustments",
            "options": {
              "multi": true
            }
          },
          {
            "type": "Control",
            "scope": "#/properties/ProgressReview/properties/planCompleted"
          }
        ]
      }
    ]
  },
  "submitLabel": "Save review"
}

{
  "schema": {
    "title": "Projects and assignments",
    "description": "A project or assignment that helps you reach a goal.",
    "type": "object",
    "required": [
      "Activity"
    ],
    "properties": {
      "Activity": {
        "type": "object",
        "title": "Activity",
