{
  "schema": {
    "type": "object",
    "required": [
      "Employee"
    ],
    "properties": {
      "Employee": {
        "type": "object",
        "title": "Employee",
        "properties": {
          "employeeId": {
            "type": "string",
            "title": "Employee number"
          },
          "managerId": {
            "type": "string",
            "title": "Manager number"
          },
          "trigger": {
            "type": "string",
            "title": "Reason for the plan",
            "enum": [
              "ANNUAL_REVIEW",
              "NEW_ROLE",
              "CAREER_GROWTH",
              "PERFORMANCE_IMPROVEMENT",
              "ONBOARDING"
            ],
            "enumNames": [
              "Annual review",
              "New role",
              "Career growth",
              "Performance improvement",
              "Onboarding"
            ]
          }
        },
        "required": [
          "employeeId",
          "managerId",
          "trigger"
        ]
      }
    }
  }
}
